Literal.Value:
'{
  "padding": 0,
  "params": [
    {
      "name": "title",
      "value": "Sales by region"
    },
    {
      "name": "columns",
      "value": 0
    },
    {
      "name": "minPanelWidth",
      "value": 130
    },
    {
      "name": "minPanelHeight",
      "value": 52
    },
    {
      "name": "sortBy",
      "value": "value"
    },
    {
      "name": "changeVs",
      "value": "first"
    },
    {
      "name": "sharedScale",
      "value": true
    },
    {
      "name": "valueFormat",
      "value": "auto"
    },
    {
      "name": "prefix",
      "value": "$"
    },
    {
      "name": "pctFormat",
      "value": "+.1%"
    },
    {
      "name": "noDataText",
      "value": "n/a"
    },
    {
      "name": "higherIsBetter",
      "value": true
    },
    {
      "name": "colorGood",
      "expr": "pbiColor(''good'')"
    },
    {
      "name": "colorBad",
      "expr": "pbiColor(''bad'')"
    },
    {
      "name": "colorNeutral",
      "expr": "pbiColor(''neutral'')"
    },
    {
      "name": "arrowUp",
      "value": "▲"
    },
    {
      "name": "arrowDown",
      "value": "▼"
    },
    {
      "name": "arrowFlat",
      "value": "►"
    },
    {
      "name": "cardColor",
      "value": "#FFFFFF"
    },
    {
      "name": "borderColor",
      "value": "#E1DFDD"
    },
    {
      "name": "borderWidth",
      "value": 1
    },
    {
      "name": "cardRadius",
      "value": 4
    },
    {
      "name": "valueColor",
      "expr": "pbiColor(0, -0.5)"
    },
    {
      "name": "labelColor",
      "value": "#605E5C"
    },
    {
      "name": "panelColor",
      "value": "#FAF9F8"
    },
    {
      "name": "panelGap",
      "value": 4
    },
    {
      "name": "lineColor",
      "expr": "pbiColor(0, -0.3)"
    },
    {
      "name": "headerH",
      "expr": "length(title) > 0 ? clamp(height * 0.14, 18, 30) : 0"
    }
  ],
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "window": [
        {
          "op": "row_number",
          "as": "rowIn"
        }
      ]
    },
    {
      "calculate": "isValid(datum[''Category'']) ? datum[''Category''] + '''' : noDataText",
      "as": "cat"
    },
    {
      "calculate": "time(toDate(datum[''Date'']))",
      "as": "t"
    },
    {
      "filter": "isFinite(datum.t)"
    },
    {
      "aggregate": [
        {
          "op": "sum",
          "field": "Value",
          "as": "vSum"
        },
        {
          "op": "valid",
          "field": "Value",
          "as": "vN"
        },
        {
          "op": "min",
          "field": "rowIn",
          "as": "firstRow"
        }
      ],
      "groupby": [
        "cat",
        "t"
      ]
    },
    {
      "filter": "datum.vN > 0"
    },
    {
      "calculate": "datum.vSum",
      "as": "v"
    },
    {
      "window": [
        {
          "op": "row_number",
          "as": "k"
        },
        {
          "op": "lag",
          "field": "v",
          "as": "prevV"
        }
      ],
      "sort": [
        {
          "field": "t",
          "order": "ascending"
        }
      ],
      "groupby": [
        "cat"
      ]
    },
    {
      "joinaggregate": [
        {
          "op": "max",
          "field": "t",
          "as": "lastT"
        },
        {
          "op": "min",
          "field": "v",
          "as": "vMin"
        },
        {
          "op": "max",
          "field": "v",
          "as": "vMax"
        },
        {
          "op": "min",
          "field": "firstRow",
          "as": "catRow"
        }
      ],
      "groupby": [
        "cat"
      ]
    },
    {
      "calculate": "datum.t === datum.lastT ? datum.v : null",
      "as": "latestPart"
    },
    {
      "calculate": "datum.t === datum.lastT ? datum.prevV : null",
      "as": "prevPart"
    },
    {
      "calculate": "datum.k === 1 ? datum.v : null",
      "as": "firstPart"
    },
    {
      "joinaggregate": [
        {
          "op": "max",
          "field": "latestPart",
          "as": "latest"
        },
        {
          "op": "max",
          "field": "prevPart",
          "as": "prev"
        },
        {
          "op": "max",
          "field": "firstPart",
          "as": "first"
        }
      ],
      "groupby": [
        "cat"
      ]
    },
    {
      "joinaggregate": [
        {
          "op": "min",
          "field": "v",
          "as": "gMin"
        },
        {
          "op": "max",
          "field": "v",
          "as": "gMax"
        },
        {
          "op": "min",
          "field": "t",
          "as": "tMin"
        },
        {
          "op": "max",
          "field": "t",
          "as": "tMax"
        },
        {
          "op": "distinct",
          "field": "cat",
          "as": "nCats"
        }
      ]
    },
    {
      "calculate": "changeVs === ''first'' ? datum.first : datum.prev",
      "as": "base"
    },
    {
      "calculate": "isValid(datum.base) && datum.base !== 0 ? (datum.latest - datum.base) / abs(datum.base) : null",
      "as": "ch"
    },
    {
      "calculate": "isValid(datum.ch) ? (higherIsBetter ? 1 : -1) * datum.ch : 0",
      "as": "g"
    },
    {
      "calculate": "sortBy === ''value'' ? -datum.latest : sortBy === ''change'' ? (isValid(datum.ch) ? -datum.g : 1e300) : sortBy === ''name'' ? 0 : datum.catRow",
      "as": "sortKey"
    },
    {
      "window": [
        {
          "op": "dense_rank",
          "as": "panel"
        }
      ],
      "sort": [
        {
          "field": "sortKey",
          "order": "ascending"
        },
        {
          "field": "cat",
          "order": "ascending"
        }
      ]
    },
    {
      "calculate": "columns > 0 ? min(columns, datum.nCats) : clamp(floor(width / minPanelWidth), 1, datum.nCats)",
      "as": "cols"
    },
    {
      "calculate": "min(ceil(datum.nCats / datum.cols), max(1, floor((height - headerH) / minPanelHeight)))",
      "as": "rowsUsed"
    },
    {
      "filter": "datum.panel <= datum.cols * datum.rowsUsed"
    },
    {
      "calculate": "width / datum.cols",
      "as": "pw"
    },
    {
      "calculate": "(height - headerH) / datum.rowsUsed",
      "as": "ph"
    },
    {
      "calculate": "((datum.panel - 1) % datum.cols) * datum.pw",
      "as": "px0"
    },
    {
      "calculate": "headerH + floor((datum.panel - 1) / datum.cols) * datum.ph",
      "as": "py0"
    },
    {
      "calculate": "clamp(min(datum.pw / 150, datum.ph / 72), 0.6, 1.8)",
      "as": "pu"
    },
    {
      "calculate": "7 * datum.pu",
      "as": "ip"
    },
    {
      "calculate": "datum.py0 + datum.ip + 12 * datum.pu",
      "as": "topY"
    },
    {
      "calculate": "datum.topY + 12 * datum.pu",
      "as": "chY"
    },
    {
      "calculate": "datum.px0 + datum.ip",
      "as": "sx0"
    },
    {
      "calculate": "datum.px0 + datum.pw - datum.ip",
      "as": "sx1"
    },
    {
      "calculate": "datum.py0 + datum.ph - datum.ip",
      "as": "sy1"
    },
    {
      "calculate": "datum.chY + min(11 * datum.pu, 0.4 * (datum.sy1 - datum.chY))",
      "as": "sy0"
    },
    {
      "calculate": "sharedScale ? datum.gMin : datum.vMin",
      "as": "lo"
    },
    {
      "calculate": "sharedScale ? datum.gMax : datum.vMax",
      "as": "hi"
    },
    {
      "calculate": "datum.tMax > datum.tMin ? datum.sx0 + (datum.t - datum.tMin) / (datum.tMax - datum.tMin) * (datum.sx1 - datum.sx0) : (datum.sx0 + datum.sx1) / 2",
      "as": "sx"
    },
    {
      "calculate": "datum.hi > datum.lo ? datum.sy1 - (datum.v - datum.lo) / (datum.hi - datum.lo) * (datum.sy1 - datum.sy0) : (datum.sy0 + datum.sy1) / 2",
      "as": "sy"
    },
    {
      "calculate": "(!isValid(datum.latest) || !isFinite(datum.latest) ? noDataText : valueFormat !== ''auto'' ? format(datum.latest, valueFormat) : (datum.latest < 0 ? ''−'' : '''') + prefix + format(abs(datum.latest) / (abs(datum.latest) >= 999.5e6 ? 1e9 : abs(datum.latest) >= 999.5e3 ? 1e6 : abs(datum.latest) >= 999.5 ? 1e3 : 1), abs(datum.latest) / (abs(datum.latest) >= 999.5e6 ? 1e9 : abs(datum.latest) >= 999.5e3 ? 1e6 : abs(datum.latest) >= 999.5 ? 1e3 : 1) < 10 ? ((abs(datum.latest) >= 999.5e6 ? 1e9 : abs(datum.latest) >= 999.5e3 ? 1e6 : abs(datum.latest) >= 999.5 ? 1e3 : 1) > 1 ? ''.1f'' : ''.2~f'') : '',.0f'') + (abs(datum.latest) >= 999.5e6 ? ''bn'' : abs(datum.latest) >= 999.5e3 ? ''M'' : abs(datum.latest) >= 999.5 ? ''K'' : ''''))",
      "as": "valueText"
    },
    {
      "calculate": "(!isValid(datum.ch) ? '''' : datum.ch > 0 ? arrowUp : datum.ch < 0 ? arrowDown : arrowFlat) + '' '' + (!isValid(datum.ch) || !isFinite(datum.ch) ? noDataText : format(datum.ch, pctFormat))",
      "as": "chText"
    },
    {
      "calculate": "(datum.g > 0 ? colorGood : datum.g < 0 ? colorBad : colorNeutral)",
      "as": "chColor"
    },
    {
      "calculate": "datum.px0 + datum.ip",
      "as": "nameX"
    },
    {
      "calculate": "datum.topY",
      "as": "nameY"
    },
    {
      "calculate": "10.5 * datum.pu",
      "as": "nameSize"
    },
    {
      "calculate": "datum.px0 + datum.pw - datum.ip",
      "as": "rightX"
    },
    {
      "calculate": "datum.topY",
      "as": "valueY"
    },
    {
      "calculate": "15 * datum.pu",
      "as": "valueSize"
    },
    {
      "calculate": "10 * datum.pu",
      "as": "chSize"
    },
    {
      "calculate": "max(20, datum.pw - 2 * datum.ip - 0.6 * datum.valueSize * length(datum.valueText) - 6 * datum.pu)",
      "as": "nameLimit"
    },
    {
      "calculate": "datum.px0 + panelGap / 2",
      "as": "bx0"
    },
    {
      "calculate": "datum.px0 + datum.pw - panelGap / 2",
      "as": "bx1"
    },
    {
      "calculate": "datum.py0 + panelGap / 2",
      "as": "by0"
    },
    {
      "calculate": "datum.py0 + datum.ph - panelGap / 2",
      "as": "by1"
    },
    {
      "calculate": "1.6 * datum.pu",
      "as": "lineW"
    },
    {
      "calculate": "PI * pow(2.6 * datum.pu, 2)",
      "as": "dotSize"
    },
    {
      "calculate": "timeFormat(datum.t, ''%-d %b %Y'')",
      "as": "tipDate"
    },
    {
      "calculate": "(!isValid(datum.v) || !isFinite(datum.v) ? noDataText : valueFormat !== ''auto'' ? format(datum.v, valueFormat) : (datum.v < 0 ? ''−'' : '''') + prefix + format(abs(datum.v) / (abs(datum.v) >= 999.5e6 ? 1e9 : abs(datum.v) >= 999.5e3 ? 1e6 : abs(datum.v) >= 999.5 ? 1e3 : 1), abs(datum.v) / (abs(datum.v) >= 999.5e6 ? 1e9 : abs(datum.v) >= 999.5e3 ? 1e6 : abs(datum.v) >= 999.5 ? 1e3 : 1) < 10 ? ((abs(datum.v) >= 999.5e6 ? 1e9 : abs(datum.v) >= 999.5e3 ? 1e6 : abs(datum.v) >= 999.5 ? 1e3 : 1) > 1 ? ''.1f'' : ''.2~f'') : '',.0f'') + (abs(datum.v) >= 999.5e6 ? ''bn'' : abs(datum.v) >= 999.5e3 ? ''M'' : abs(datum.v) >= 999.5 ? ''K'' : ''''))",
      "as": "tipValue"
    }
  ],
  "layer": [
    {
      "description": "Card background and border, inset by half the border so the container never clips it",
      "data": {
        "values": [
          {}
        ]
      },
      "mark": {
        "type": "rect",
        "x": {
          "expr": "borderWidth / 2"
        },
        "y": {
          "expr": "borderWidth / 2"
        },
        "x2": {
          "expr": "width - borderWidth / 2"
        },
        "y2": {
          "expr": "height - borderWidth / 2"
        },
        "fill": {
          "expr": "cardColor"
        },
        "stroke": {
          "expr": "borderColor"
        },
        "strokeWidth": {
          "expr": "borderWidth"
        },
        "cornerRadius": {
          "expr": "cardRadius"
        }
      }
    },
    {
      "description": "Title, when set",
      "data": {
        "values": [
          {}
        ]
      },
      "transform": [
        {
          "filter": "length(title) > 0"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "alphabetic",
        "fontWeight": 600,
        "x": {
          "expr": "8"
        },
        "y": {
          "expr": "headerH * 0.7"
        },
        "fontSize": {
          "expr": "headerH * 0.5"
        },
        "limit": {
          "expr": "width - 2 * panelGap"
        },
        "fill": {
          "expr": "labelColor"
        },
        "text": {
          "expr": "title"
        }
      }
    },
    {
      "description": "Panel backgrounds, one per category",
      "transform": [
        {
          "filter": "datum.t === datum.lastT"
        }
      ],
      "mark": {
        "type": "rect",
        "fill": {
          "expr": "panelColor"
        },
        "cornerRadius": 3
      },
      "encoding": {
        "x": {
          "field": "bx0",
          "type": "quantitative",
          "scale": null
        },
        "x2": {
          "field": "bx1"
        },
        "y": {
          "field": "by0",
          "type": "quantitative",
          "scale": null
        },
        "y2": {
          "field": "by1"
        }
      }
    },
    {
      "description": "Category name",
      "transform": [
        {
          "filter": "datum.t === datum.lastT"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "alphabetic",
        "fontWeight": 600,
        "fill": {
          "expr": "labelColor"
        },
        "limit": {
          "expr": "datum.nameLimit"
        }
      },
      "encoding": {
        "text": {
          "field": "cat",
          "type": "nominal"
        },
        "x": {
          "field": "nameX",
          "type": "quantitative",
          "scale": null
        },
        "y": {
          "field": "nameY",
          "type": "quantitative",
          "scale": null
        },
        "size": {
          "field": "nameSize",
          "type": "quantitative",
          "scale": null
        }
      }
    },
    {
      "description": "Sparkline, one per category",
      "mark": {
        "type": "line",
        "stroke": {
          "expr": "lineColor"
        },
        "strokeJoin": "round"
      },
      "encoding": {
        "x": {
          "field": "sx",
          "type": "quantitative",
          "scale": null
        },
        "y": {
          "field": "sy",
          "type": "quantitative",
          "scale": null
        },
        "detail": {
          "field": "cat",
          "type": "nominal"
        },
        "strokeWidth": {
          "field": "lineW",
          "type": "quantitative",
          "scale": null
        },
        "tooltip": [
          {
            "field": "cat",
            "type": "nominal",
            "title": "Category"
          },
          {
            "field": "tipDate",
            "type": "nominal",
            "title": "Date"
          },
          {
            "field": "tipValue",
            "type": "nominal",
            "title": "Value"
          }
        ]
      }
    },
    {
      "description": "Latest point",
      "transform": [
        {
          "filter": "datum.t === datum.lastT"
        }
      ],
      "mark": {
        "type": "point",
        "filled": true,
        "opacity": 1,
        "shape": "circle"
      },
      "encoding": {
        "x": {
          "field": "sx",
          "type": "quantitative",
          "scale": null
        },
        "y": {
          "field": "sy",
          "type": "quantitative",
          "scale": null
        },
        "size": {
          "field": "dotSize",
          "type": "quantitative",
          "scale": null
        },
        "color": {
          "field": "chColor",
          "type": "nominal",
          "scale": null
        }
      }
    },
    {
      "description": "Latest value",
      "transform": [
        {
          "filter": "datum.t === datum.lastT"
        }
      ],
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "alphabetic",
        "fontWeight": "bold",
        "fill": {
          "expr": "valueColor"
        }
      },
      "encoding": {
        "text": {
          "field": "valueText",
          "type": "nominal"
        },
        "x": {
          "field": "rightX",
          "type": "quantitative",
          "scale": null
        },
        "y": {
          "field": "valueY",
          "type": "quantitative",
          "scale": null
        },
        "size": {
          "field": "valueSize",
          "type": "quantitative",
          "scale": null
        },
        "tooltip": [
          {
            "field": "cat",
            "type": "nominal",
            "title": "Category"
          },
          {
            "field": "valueText",
            "type": "nominal",
            "title": "Latest"
          },
          {
            "field": "chText",
            "type": "nominal",
            "title": "Change"
          }
        ]
      }
    },
    {
      "description": "Change, coloured good or bad",
      "transform": [
        {
          "filter": "datum.t === datum.lastT"
        }
      ],
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "alphabetic",
        "fontWeight": 600
      },
      "encoding": {
        "text": {
          "field": "chText",
          "type": "nominal"
        },
        "x": {
          "field": "rightX",
          "type": "quantitative",
          "scale": null
        },
        "y": {
          "field": "chY",
          "type": "quantitative",
          "scale": null
        },
        "size": {
          "field": "chSize",
          "type": "quantitative",
          "scale": null
        },
        "color": {
          "field": "chColor",
          "type": "nominal",
          "scale": null
        }
      }
    }
  ]
}'
